#include <vector>
#include <list>
#include <algorithm>
#include <iostream>

int main() {
   std::vector<int> coll1 = {1, 2, 3, 4, 5};
   std::list<int> coll2 = {6, 7, 8, 9, 10};

   // Using range-based for loop to print elements of coll1
   for (int element : coll1) {
       std::cout << element << ' ';
   }
   std::cout << '
';

   // Using range-based for loop to modify elements of coll2
   for (auto& element : coll2) {
       element *= 2; // double each element
   }

   // Print modified coll2
   for (const auto& element : coll2) {
       std::cout << element << ' ';
   }
   std::cout << '
';

   return 0;
}
